import{describe,it,expect}from"vitest";import{nodes,links,filterNodes,getConnectedNodes,findNodeById,getUniqueCategories,getUniqueRegions,buildJourneyFlow,presetJourneys}from"../../frontend/cultural-dna/cultural-dna.js";const REQUIRED_NODE_FIELDS=["id","name","category","region","description","significance","icon","tags"],REQUIRED_LINK_FIELDS=["source","target","relationship","strength","description"];describe("Cultural DNA Nodes Integrity",()=>{it("contains at least 30 cultural nodes in the dataset",()=>{expect(nodes.length).toBeGreaterThanOrEqual(30)}),it("every node contains all required fields with non-empty values",()=>{nodes.forEach((e,t)=>{REQUIRED_NODE_FIELDS.forEach(o=>{expect(e,`Node at index ${t} missing field ${o}`).toHaveProperty(o),"tags"===o?(expect(Array.isArray(e.tags)).toBe(!0),expect(e.tags.length).toBeGreaterThan(0)):(expect(typeof e[o]).toBe("string"),expect(e[o].trim().length).toBeGreaterThan(0))})})}),it("all node IDs are unique",()=>{const e=nodes.map(e=>e.id),t=new Set(e);expect(t.size).toBe(e.length)}),it("all node names are unique",()=>{const e=nodes.map(e=>e.name),t=new Set(e);expect(t.size).toBe(e.length)}),it("covers all 7 core categories",()=>{const e=new Set(nodes.map(e=>e.category));expect(e.size).toBe(7),expect(e.has("Languages")).toBe(!0),expect(e.has("Architecture")).toBe(!0),expect(e.has("Cuisine")).toBe(!0),expect(e.has("Music & Dance")).toBe(!0),expect(e.has("Clothing & Textiles")).toBe(!0),expect(e.has("Festivals")).toBe(!0),expect(e.has("Traditions & Philosophy")).toBe(!0)})}),describe("Cultural DNA Links & Network Integrity",()=>{it("contains at least 30 influence links in the network",()=>{expect(links.length).toBeGreaterThanOrEqual(30)}),it("every link contains all required fields with valid types",()=>{links.forEach((e,t)=>{REQUIRED_LINK_FIELDS.forEach(o=>{expect(e,`Link at index ${t} missing field ${o}`).toHaveProperty(o),"strength"===o?(expect(typeof e[o]).toBe("number"),expect(e[o]).toBeGreaterThanOrEqual(1)):(expect(typeof e[o]).toBe("string"),expect(e[o].trim().length).toBeGreaterThan(0))})})}),it("every link references existing node IDs for both source and target",()=>{const e=new Set(nodes.map(e=>e.id));links.forEach((t,o)=>{expect(e.has(t.source),`Link at index ${o} source "${t.source}" does not exist`).toBe(!0),expect(e.has(t.target),`Link at index ${o} target "${t.target}" does not exist`).toBe(!0)})})}),describe("Cultural DNA Search & Filtering",()=>{it("returns all nodes when search query and filters are default",()=>{const e=filterNodes(nodes);expect(e.length).toBe(nodes.length)}),it("filters nodes by search query (e.g. Biryani)",()=>{const e=filterNodes(nodes,{search:"Biryani"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{const t=[e.name,e.category,e.region,e.description,e.significance,...e.tags||[]].some(e=>e&&e.toLowerCase().includes("biryani"));expect(t).toBe(!0)})}),it("filters nodes by category (e.g. Cuisine)",()=>{const e=filterNodes(nodes,{category:"cuisine"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.category.toLowerCase()).toBe("cuisine")})}),it("filters nodes by region (e.g. South)",()=>{const e=filterNodes(nodes,{region:"South"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.region.toLowerCase().includes("south")).toBe(!0)})}),it("combines search, category, and region filters correctly",()=>{const e=filterNodes(nodes,{search:"saree",category:"Clothing & Textiles",region:"all"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.category).toBe("Clothing & Textiles"),expect(e.name.toLowerCase().includes("saree")||e.description.toLowerCase().includes("saree")).toBe(!0)})})}),describe("Cultural DNA Traversal & Journey Generation",()=>{it("finds node by ID correctly",()=>{const e=findNodeById("sanskrit");expect(e).toBeDefined(),expect(e.name).toBe("Sanskrit")}),it("returns connected nodes showing direct incoming/outgoing influences",()=>{const e=getConnectedNodes("sufi-qawwali",links,nodes);expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e).toHaveProperty("node"),expect(e).toHaveProperty("type"),expect(e).toHaveProperty("relationship"),expect(e).toHaveProperty("strength"),expect(e).toHaveProperty("description")})}),it("extracts unique categories sorted alphabetically",()=>{const e=getUniqueCategories(nodes);expect(e.length).toBe(7);for(let t=1;t<e.length;t++)expect(e[t-1].localeCompare(e[t])).toBeLessThanOrEqual(0)}),it("extracts unique regions",()=>{const e=getUniqueRegions(nodes);expect(e.length).toBeGreaterThan(0),expect(e).toContain("North"),expect(e).toContain("South")}),it("builds detailed step-by-step journey flow paths",()=>{const e=buildJourneyFlow(["sufism-bhakti","sufi-qawwali","spring-holi"],links,nodes);expect(e.length).toBe(2),expect(e[0].source.id).toBe("sufism-bhakti"),expect(e[0].target.id).toBe("sufi-qawwali"),expect(e[0].linked).toBe(!0),expect(e[1].source.id).toBe("sufi-qawwali"),expect(e[1].target.id).toBe("spring-holi")}),it("verifies preset journeys configuration",()=>{Object.keys(presetJourneys).forEach(e=>{const t=presetJourneys[e];expect(t).toHaveProperty("name"),expect(t).toHaveProperty("description"),expect(t).toHaveProperty("steps"),expect(t.steps.length).toBeGreaterThanOrEqual(3)})})});